-- Starting data for Taea's list of 2026-10-22, from official pages checked 2026-10-22. Safe to run twice.

-- Foster programs at the shelters and rescues the site covers. "free" = the program says the animal's care and supplies are covered at no cost.

-- Pack Adventures: the city's page adds weather rules.
update public.sniffari_programs set facts = array['7 days a week', 'Check out from 11 AM, back by 4 PM', 'Ages 18+', 'Waiver and ID required', 'No trips in extreme heat, cold or storms']::text[], checked_on = date '2026-10-22' where program_name = 'Pack Adventures' and not ('No trips in extreme heat, cold or storms' = any(facts));

-- Where to report animal cruelty or neglect, by city (official city and county pages).

-- Wildlife groups and places to learn about and support wildlife (not rehab hotlines; those are under "wildlife").

-- Credit cards, loans and payment plans: drafts, hidden until Taea switches on the ones that have helped.
update public.help_resources set best_for = 'A big vet bill you can pay off before the no-interest offer ends.' where name ilike 'CareCredit%' and best_for is null;
