insert into public.help_resources (category, name, kind, description, best_for, caution, link_url, phone, area, checked_on, published, sort) select 'financing', 'Scratchpay', 'Loan', 'A loan for vet bills, paid back in fixed monthly payments over 12 to 24 months. Made by WebBank. Checking if you qualify doesn''t affect your credit score. Taken at many vet hospitals.', 'Splitting a vet bill into set monthly payments, with no deferred interest.', 'This is a loan, not financial assistance. Interest can be up to 36% a year.', 'https://scratchpay.com/', null, null, date '2026-10-22', false, 20 where not exists (select 1 from public.help_resources where name = 'Scratchpay');
insert into public.help_resources (category, name, kind, description, best_for, caution, link_url, phone, area, checked_on, published, sort) select 'financing', 'Sunbit', 'Loan', 'Pay over time at the vet''s checkout, with part of the bill due that day. Made by TAB Bank. No hard credit check, but payments are reported to a credit bureau.', 'Spreading out a bill at a clinic that offers it, when you can pay part of it now.', 'This is a loan, not financial assistance. Interest can be up to 35.99% a year.', 'https://sunbit.com/', null, null, date '2026-10-22', false, 30 where not exists (select 1 from public.help_resources where name = 'Sunbit');
insert into public.help_resources (category, name, kind, description, best_for, caution, link_url, phone, area, checked_on, published, sort) select 'financing', 'Varidi', 'Payment plan', 'Payment plans some vet clinics offer through Varidi, paid automatically from your card. No hard credit check and no interest, though a setup fee may apply.', 'Splitting a bill at a clinic that uses it. Ask your vet.', 'Only at clinics that offer it, and on the clinic''s terms.', 'https://varidi.com/for-customers/', null, null, date '2026-10-22', false, 40 where not exists (select 1 from public.help_resources where name = 'Varidi');
insert into public.help_resources (category, name, kind, description, best_for, caution, link_url, phone, area, checked_on, published, sort) select 'financing', 'VetBilling', 'Payment plan', 'Payment plans run by your vet''s office through VetBilling. The clinic decides who qualifies and sets the terms. No credit check needed.', 'Splitting a bill at a clinic that uses it. Ask your vet.', 'Only at clinics that offer it, and on the clinic''s terms.', 'https://vetbilling.com/', null, null, date '2026-10-22', false, 50 where not exists (select 1 from public.help_resources where name = 'VetBilling');
